using System.Collections.ObjectModel; using System.Windows; using System.Windows.Input; using ExamRosterApp.Application; using ExamRosterApp.Domain;
namespace ExamRosterApp.Desktop;
public class MainViewModel{public ObservableCollection<Teacher> Teachers {get;}=new(); public ObservableCollection<ExamDutySlot> Slots {get;}=new(); public ObservableCollection<object> Assignments {get;}=new(); public ObservableCollection<TeacherDutySummary> Fairness {get;}=new(); public ICommand GenerateRosterCommand{get;} public ICommand ClearRosterCommand{get;} public MainViewModel(IRosterService roster, ITeacherService t, IExamDutySlotService s){GenerateRosterCommand=new AsyncRelay(async()=>{var r=await roster.GenerateAndSaveRosterAsync(); MessageBox.Show(string.Join("\n",r.Warnings));}); ClearRosterCommand=new AsyncRelay(()=>roster.ClearRosterAsync());}}
public class AsyncRelay(Func<Task> run):ICommand{public event EventHandler? CanExecuteChanged; public bool CanExecute(object? p)=>true; public async void Execute(object? p)=>await run();}
